R_API void r_bin_mem_free(void *data) {
        RBinMem *mem = (RBinMem *)data;
        if (mem && mem->mirrors) {
                mem->mirrors->free = r_bin_mem_free;
                r_list_free (mem->mirrors);
                mem->mirrors = NULL;
