static int reloc_cmp(void *incoming, void *in, void *user) {
        RBinReloc *_incoming = (RBinReloc *)incoming;
        RBinReloc *_in = (RBinReloc *)in;
        if (_incoming->vaddr > _in->vaddr) {
                return 1;
        }
        if (_incoming->vaddr < _in->vaddr) {
                return -1;
        }
        return 0;
}

